+102|    /** Counts the elements that fell into a session window. */
+103|    public static final class CountSession
+104|            extends ProcessWindowFunction<TaskEvent, Tuple2<Long, Integer>, Long, TimeWindow> {
+105|
+106|        @Override
+107|        public void process(Long jobId,
+108|                            Context ctx,
+109|                            Iterable<TaskEvent> elements,
+110|                            Collector<Tuple2<Long, Integer>> out) {
+111|            int n = 0;
+112|            for (TaskEvent ignored : elements) {
+113|                n++;
+114|            }
+115|            out.collect(Tuple2.of(jobId, n));
+116|        }
